package io.github.carlos_emr.carlos.form.model.rehab;

import io.github.carlos_emr.carlos.form.model.rehab.RehabStudyColumn.Checkbox;
import jakarta.persistence.Column;
import jakarta.persistence.Entity;
import jakarta.persistence.Table;
import java.util.List;

/**
 * Every column of the unchanged {@code formTreatmentPref} table: the Treatment Preference
 * questionnaire of the 2004 rehabilitation study.
 *
 * <p>Generated by {@code scripts/forms/generate_rehab_study_entities.py} from the Flyway
 * baseline; regenerate rather than edit. {@code RehabStudyEntitySchemaContractUnitTest}
 * fails the build when this mapping and the baseline table disagree.</p>
 *
 * @since 2026-11-26
 */
@Entity
@Table(name = "formTreatmentPref")
public class FormTreatmentPref extends RehabStudyAssessment {
    private static final long serialVersionUID = 1L;

    private static final List<RehabStudyColumn<FormTreatmentPref>> COLUMNS = List.of(
            new Checkbox<>("treatmentGr", form -> form.treatmentGr, (form, value) -> form.treatmentGr = value),
            new Checkbox<>("controlGr", form -> form.controlGr, (form, value) -> form.controlGr = value),
            new Checkbox<>("eitherGr", form -> form.eitherGr, (form, value) -> form.eitherGr = value));

    @Column(name = "treatmentGr", columnDefinition = "tinyint(1)")
    private Byte treatmentGr;
    @Column(name = "controlGr", columnDefinition = "tinyint(1)")
    private Byte controlGr;
    @Column(name = "eitherGr", columnDefinition = "tinyint(1)")
    private Byte eitherGr;

    /** The answer columns in physical order; the shared header is mapped by the superclass. */
    public static List<RehabStudyColumn<FormTreatmentPref>> columns() {
        return COLUMNS;
    }
}
